        nonlocal pos
        while pos < len(expr) and expr[pos] == ' ':
            pos += 1

    def parse_number():
        nonlocal pos
        skip_whitespace()
        start = pos
        while pos < len(expr) and expr[pos].isdigit():
            pos += 1
        return int(expr[start:pos])

    def parse_unary():
        nonlocal pos
        skip_whitespace()

        # Handle unary minus
        sign = 1
        while pos < len(expr) and expr[pos] == '-':
            pos += 1
            sign *= -1
            skip_whitespace()

        # Handle parenthesized expression or number
        if pos < len(expr) and expr[pos] == '(':
            pos += 1  # consume '('
            val = parse_addition()
            skip_whitespace()
            pos += 1  # consume ')'
        else:
            val = parse_number()

        return sign * val

    def parse_multiplication():
        nonlocal pos
        left = parse_unary()

        while True:
            skip_whitespace()
            if pos >= len(expr) or expr[pos] not in '*/':
                break

            op = expr[pos]
            pos += 1
            right = parse_unary()

            if op == '*':
                left = left * right
            else:  # op == '/'
                # Integer division truncating toward zero
                if left * right >= 0:
                    left = left // right
                else:
                    left = -(-left // right) if left < 0 else -(left // -right)

        return left

    def parse_addition():
