            skip_whitespace()
            if pos >= len(expr) or expr[pos] not in '+-':
                break

            # Check if '+' or '-' is binary (not unary)
            if expr[pos] == '-' and pos > 0:
                # Look back to see if previous token could be an operand
                temp_pos = pos - 1
                while temp_pos >= 0 and expr[temp_pos] == ' ':
                    temp_pos -= 1
                if temp_pos >= 0 and (expr[temp_pos].isdigit() or expr[temp_pos] == ')'):
                    # It's binary
                    op = expr[pos]
                    pos += 1
                    right = parse_multiplication()
                    if op == '+':
                        left = left + right
                    else:
                        left = left - right
                else:
                    # It's unary, stop here
                    break
            elif expr[pos] == '+':
                op = expr[pos]
                pos += 1
                right = parse_multiplication()
                left = left + right
            else:
                break

        return left

